import sys

# Increase recursion depth just in case
sys.setrecursionlimit(300000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator)) - 1  # 0-based index

        A = [int(next(iterator)) for _ in range(N)]
        B = [int(next(iterator)) for _ in range(N)]
        P = [int(next(iterator)) - 1 for _ in range(N)]
        Q = [int(next(iterator)) - 1 for _ in range(N)]
    except StopIteration:
        return

    # Helper to find cycle of target and distances
    # Returns a dictionary mapping node -> distance to target in the cycle
    def get_cycle_info(target, perm):
        # Find inverse permutation to traverse backwards from target
        inv = [0] * N
        for i in range(N):
            inv[perm[i]] = i

        # Traverse backwards from target
        dist = {}
        curr = target
        d = 0
        while True:
            dist[curr] = d
            curr = inv[curr]
            d += 1
            if curr == target:
                break

        return dist

    # Process Red balls
    dist_P = get_cycle_info(X, P)

    # Check if all red balls are in the cycle of X
    possible_P = True
    max_dist_P = -1
    for i in range(N):
        if A[i] == 1:
            if i not in dist_P:
                possible_P = False
                break
            if i != X:
                if dist_P[i] > max_dist_P:
                    max_dist_P = dist_P[i]

    if not possible_P:
        print(-1)
        return

    # Process Blue balls
    dist_Q = get_cycle_info(X, Q)

    possible_Q = True
    max_dist_Q = -1
    for i in range(N):
        if B[i] == 1:
            if i not in dist_Q:
                possible_Q = False
                break
            if i != X:
                if dist_Q[i] > max_dist_Q:
                    max_dist_Q = dist_Q[i]

    if not possible_Q:
        print(-1)
        return

    # Build S_P and S_Q
    # S_P contains nodes u in cycle_P such that 1 <= dist_P[u] <= max_dist_P
    # These are the nodes that must be operated on to move red balls to X
    S_P = set()
    if max_dist_P >= 0:
        for u in dist_P:
            if 1 <= dist_P[u] <= max_dist_P:
                S_P.add(u)

    S_Q = set()
    if max_dist_Q >= 0:
        for u in dist_Q:
            if 1 <= dist_Q[u] <= max_dist_Q:
                S_Q.add(u)

    S = S_P.union(S_Q)

    # Build dependency graph
    # Nodes are in S
    # Edges: u -> P[u] if u in S_P and P[u] in S
    #        u -> Q[u] if u in S_Q and Q[u] in S
    # This represents the order constraint: u must be operated before P[u] (or Q[u])

    adj = [[] for _ in range(N)]
    for u in S:
        if u in S_P:
            v = P[u]
            if v in S:
                adj[u].append(v)
        if u in S_Q:
            v = Q[u]
            if v in S:
                adj[u].append(v)

    # Cycle detection using iterative DFS
    # Colors: 0 = unvisited, 1 = visiting, 2 = visited
    color = [0] * N

    has_cycle = False

    # We only need to check nodes in S
    for start_node in S:
        if color[start_node] != 0:
            continue

        stack = [start_node]
        color[start_node] = 1

        while stack:
            u = stack[-1]

            # Find an unvisited neighbor
            found_unvisited = False
            for v in adj[u]:
                if color[v] == 1:
                    has_cycle = True
                    break
                if color[v] == 0:
                    color[v] = 1
                    stack.append(v)
                    found_unvisited = True
                    break

            if has_cycle:
                break

            if not found_unvisited:
                color[u] = 2
                stack.pop()

        if has_cycle:
            break

    if has_cycle:
        print(-1)
    else:
        print(len(S))

if __name__ == '__main__':
    solve()
