import sys
from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # dp[j][l] stores the minimum sum using exactly j operations of type 1 and l operations of type 2
        # Initialize with infinity
        INF = float('inf')
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            # Iterate backwards to update dp table in-place
            # This ensures that when we compute dp[j][l], we are using values from the previous iteration (old values)
            # for dp[j-1][l], dp[j][l-1], and dp[j-1][l-1].
            for j in range(op1, -1, -1):
                for l in range(op2, -1, -1):
                    # Option 0: No Op on current element x
                    # We add x to the sum accumulated so far with j Op1s and l Op2s
                    res = dp[j][l] + x

                    # Option 1: Op1 on current element x
                    # Requires j > 0. We transition from dp[j-1][l] (old)
                    if j > 0:
                        prev_j = dp[j-1][l]
                        if prev_j != INF:
                            val = (x + 1) // 2
                            res = min(res, prev_j + val)

                    # Option 2: Op2 on current element x
                    # Requires l > 0 and x >= k. We transition from dp[j][l-1] (old)
                    if l > 0:
                        prev_l = dp[j][l-1]
                        if prev_l != INF and x >= k:
                            val = x - k
                            res = min(res, prev_l + val)

                    # Option 3: Both Op1 and Op2 on current element x
                    # Requires j > 0 and l > 0. We transition from dp[j-1][l-1] (old)
                    if j > 0 and l > 0:
                        prev_both = dp[j-1][l-1]
                        if prev_both != INF:
                            # Order 1: Op1 then Op2
                            # Valid if ceil(x/2) >= k
                            val1 = (x + 1) // 2
                            if val1 >= k:
                                res = min(res, prev_both + (val1 - k))
                            # Order 2: Op2 then Op1
                            # Valid if x >= k
                            if x >= k:
                                val2 = x - k
                                res = min(res, prev_both + ((val2 + 1) // 2))

                    dp[j][l] = res

        ans = INF
        for j in range(op1 + 1):
            for l in range(op2 + 1):
                if dp[j][l] < ans:
                    ans = dp[j][l]

        return ans

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    # Parse nums from the first line
    line1 = input_data[0].strip()
    if line1.startswith('[') and line1.endswith(']'):
        line1 = line1[1:-1]
    if line1:
        nums = list(map(int, line1.split(',')))
    else:
        nums = []

    # Parse k, op1, op2 from subsequent lines
    tokens = []
    for i in range(1, len(input_data)):
        tokens.extend(input_data[i].strip().split())

    if len(tokens) >= 3:
        k = int(tokens[0])
        op1 = int(tokens[1])
        op2 = int(tokens[2])
    else:
        return

    sol = Solution()
    print(sol.minArraySum(nums, k, op1, op2))

if __name__ == "__main__":
    solve()
